#!/usr/bin/env node
/**
 * Generates the strategy modules (`src/strategies/<strategy>/index.ts` + `number.ts`) and the
 * root sub-path proxy folders (`power/package.json`, …).
 *
 *   node scripts/generate.js          # write files
 *   node scripts/generate.js --check  # fail if generated files are stale (CI)
 */
'use strict';

const fs = require('fs');
const path = require('path');
const prettier = require('prettier');
const {STRATEGIES, AXES, INVERTER_DOC, kernelSpecs, facilitatorSpecs} = require('./naming');

const ROOT = path.resolve(__dirname, '..');
const CHECK = process.argv.includes('--check');
const HEADER =
  '/* AUTO-GENERATED by scripts/generate.js — do not edit by hand. Run `npm run generate`. */\n';

const INVERTER_INDEX = {
  DEFAULT: 0,
  PH_TO_LW: 1,
  PW_TO_LH: 2,
  LH_TO_PW: 3,
  LW_TO_PH: 4,
  SW_TO_LH: 5,
  SW_TO_LW: 6,
  SW_TO_PH: 7,
  SW_TO_PW: 8,
};

const UNIT_DOC = {dp: 'dp', sp: 'sp (font-scaled)', em: 'sp (ignores font scale)'};

function kernelDoc(s, spec) {
  const parts = [s.name, spec.axis.qualifier];
  const invDoc = INVERTER_DOC[spec.inv[1]];
  if (invDoc) parts.push(`→ ${invDoc}`);
  if (spec.flag[1] & 1) parts.push('aspect ratio');
  if (spec.flag[1] & 2) parts.push('ignore multi-window');
  parts.push(spec.px ? `px of ${UNIT_DOC[spec.family.unit]}` : UNIT_DOC[spec.family.unit]);
  return parts.join(' · ');
}

function genIndex(s) {
  const L = [];
  L.push(HEADER);
  L.push(`/**
 * ${s.name} strategy — React Native port of \`com.appdimens.dynamic.compose.${s.dir}\` /
 * \`code.${s.dir}\`. Names mirror the Android API${s.prefix ? ` with the \`${s.prefix}\` prefix` : ''}.
 *
 * Every function is O(1): one snapshot load, one cached factor read and one multiply.
 */`);
  L.push(`import {ScalingStrategy, DpQualifier} from '../../core/types';`);
  L.push(`import type {DimenFn, SpFacilitatorOptions} from '../../core/types';`);
  L.push(`import {
  Kind,
  kernel,
  rotateFactory,
  modeFactory,
  qualifierFactory,
  screenFactory,
  toDynamicFactory,
  toDynamicSpFactory,
} from '../../core/kernels';`);
  L.push(
    `import type {RotateFn, ModeFn, QualifierFn, ScreenFn, ToDynamicFn, ToDynamicSpFn} from '../../core/kernels';`,
  );
  L.push(`import {DimenDpBuilder, DimenSpBuilder} from '../../core/builder';`);
  if (s.dir === 'percent') L.push(`export * from '../../core/percentSpace';`);
  L.push('');
  L.push(`const S = ScalingStrategy.${s.id};`);
  L.push('');
  L.push('// ── Kernels ─────────────────────────────────────────────────────────────────');
  const qIdx = {SW: 0, H: 1, W: 2};
  for (const spec of kernelSpecs(s)) {
    const kind = spec.px ? spec.family.pxKind : spec.family.kind;
    L.push(`/** ${kernelDoc(s, spec)} */`);
    L.push(
      `export const ${spec.name}: DimenFn = kernel(S, ${qIdx[spec.axis.q]}, ${INVERTER_INDEX[spec.inv[1]]}, ${spec.flag[1]}, Kind.${kind});`,
    );
  }
  L.push('');
  L.push('// ── Conditional facilitators ────────────────────────────────────────────────');
  const factory = {
    Rotate: 'rotateFactory',
    Mode: 'modeFactory',
    Qualifier: 'qualifierFactory',
    Screen: 'screenFactory',
  };
  const fnType = {Rotate: 'RotateFn', Mode: 'ModeFn', Qualifier: 'QualifierFn', Screen: 'ScreenFn'};
  for (const f of facilitatorSpecs(s)) {
    const sp = f.unit === 'sp';
    const type = sp ? `${fnType[f.fam]}<SpFacilitatorOptions>` : fnType[f.fam];
    const what = f.plain
      ? 'receiver is an already-resolved value; only the alternate is scaled when active'
      : 'both branches are scaled';
    L.push(
      `/** ${s.name} ${f.fam.toLowerCase()} facilitator on ${f.axis.qualifier}${f.px ? ' (px)' : ''} — ${what}. */`,
    );
    L.push(
      `export const ${f.name}: ${type} = ${factory[f.fam]}(S, ${qIdx[f.axis.q]}, ${sp}, ${f.px}, ${f.plain});`,
    );
  }
  L.push('');
  L.push('// ── Escape hatches (Android `toDynamic*`) ──────────────────────────────────');
  L.push(`/** Scales \`value\` in dp with every parameter explicit. */`);
  L.push(`export const toDynamic${s.name}Dp: ToDynamicFn = toDynamicFactory(S, false);`);
  L.push(`/** Scales \`value\` in px with every parameter explicit. */`);
  L.push(`export const toDynamic${s.name}Px: ToDynamicFn = toDynamicFactory(S, true);`);
  L.push(`/** Scales a font size (sp) with every parameter explicit. */`);
  L.push(`export const toDynamic${s.name}Sp: ToDynamicSpFn = toDynamicSpFactory(S, false);`);
  L.push(`/** Scales a font size to px with every parameter explicit. */`);
  L.push(`export const toDynamic${s.name}SpPx: ToDynamicSpFn = toDynamicSpFactory(S, true);`);
  L.push('');
  L.push('// ── Builders ────────────────────────────────────────────────────────────────');
  L.push(`/**
 * ${s.name} dp builder (Android \`${s.dpBuilder}\`). Immutable; values resolve on access.
 *
 * @example
 * const card = ${s.lower}Dp(120).screen(UiModeType.TELEVISION, 200).screen(DpQualifier.SMALL_WIDTH, 600, 180);
 * <View style={{width: card.${s.prefix}sdp}} />
 */`);
  L.push(`export class ${s.dpBuilder} extends DimenDpBuilder {`);
  L.push(`  constructor(initialBaseValue: number) {\n    super(S, initialBaseValue);\n  }`);
  for (const a of AXES) {
    L.push(`  /** Resolved on ${a.qualifier} (dp). */`);
    L.push(
      `  get ${s.prefix}${a.axis}dp(): number {\n    return this.dp(DpQualifier.${a.qualifier});\n  }`,
    );
    L.push(`  /** Resolved on ${a.qualifier} (px). */`);
    L.push(
      `  get ${s.prefix}${a.axis}dpPx(): number {\n    return this.px(DpQualifier.${a.qualifier});\n  }`,
    );
  }
  L.push('}');
  L.push(`/** Creates a ${s.name} dp builder (Android \`Number.${s.lower}Dp()\`). */`);
  L.push(
    `export function ${s.lower}Dp(initialBaseValue: number): ${s.dpBuilder} {\n  return new ${s.dpBuilder}(initialBaseValue);\n}`,
  );
  L.push(
    `/** ${s.name} sp builder (Android \`${s.spBuilder}\`). Immutable; values resolve on access. */`,
  );
  L.push(`export class ${s.spBuilder} extends DimenSpBuilder {`);
  L.push(`  constructor(initialBaseValue: number) {\n    super(S, initialBaseValue);\n  }`);
  for (const a of AXES) {
    L.push(`  /** Font size on ${a.qualifier} (font scale applied by React Native). */`);
    L.push(
      `  get ${s.prefix}${a.axis}sp(): number {\n    return this.sp(DpQualifier.${a.qualifier});\n  }`,
    );
    L.push(`  /** Font size on ${a.qualifier} ignoring the font scale. */`);
    L.push(
      `  get ${s.prefix}${a.axis}em(): number {\n    return this.em(DpQualifier.${a.qualifier});\n  }`,
    );
    L.push(`  /** Font size on ${a.qualifier} in px. */`);
    L.push(
      `  get ${s.prefix}${a.axis}spPx(): number {\n    return this.spPx(DpQualifier.${a.qualifier});\n  }`,
    );
    L.push(`  /** Font size on ${a.qualifier} in px ignoring the font scale. */`);
    L.push(
      `  get ${s.prefix}${a.axis}emPx(): number {\n    return this.emPx(DpQualifier.${a.qualifier});\n  }`,
    );
  }
  L.push('}');
  L.push(`/** Creates a ${s.name} sp builder (Android \`Number.${s.lower}Sp()\`). */`);
  L.push(
    `export function ${s.lower}Sp(initialBaseValue: number): ${s.spBuilder} {\n  return new ${s.spBuilder}(initialBaseValue);\n}`,
  );
  L.push('');
  L.push(
    `/** Every kernel of this strategy, keyed by name (used by number extensions and DimenStyleSheet). */`,
  );
  L.push(`export const ${s.lower}Kernels: Readonly<Record<string, DimenFn>> = {`);
  for (const spec of kernelSpecs(s)) L.push(`  ${spec.name},`);
  L.push('};');
  return L.join('\n') + '\n';
}

function genNumber(s) {
  const L = [];
  L.push(HEADER);
  L.push(`/**
 * Opt-in \`Number.prototype\` extensions for the ${s.name} strategy, so values read like the
 * Android API: \`(16).${s.prefix}sdp\`, \`(14).${s.prefix}ssp\`.
 *
 *   import 'appdimens-react-native/${s.dir === 'scaled' ? 'number' : `${s.dir}/number`}';
 */`);
  L.push(`import {installNumberExtensions} from '../../core/numberExtensions';`);
  L.push(`import {${s.lower}Kernels} from './index';`);
  L.push('');
  L.push(`installNumberExtensions(${s.lower}Kernels);`);
  L.push('');
  L.push('declare global {');
  L.push('  interface Number {');
  for (const spec of kernelSpecs(s)) {
    L.push(`    /** ${kernelDoc(s, spec)} */`);
    L.push(`    readonly ${spec.name}: number;`);
  }
  L.push('  }');
  L.push('}');
  L.push('');
  L.push('export {};');
  return L.join('\n') + '\n';
}

function proxy(name, target) {
  return (
    JSON.stringify(
      {
        name: `appdimens-react-native/${name}`,
        private: true,
        main: `${target.rel}/lib/commonjs/${target.path}.js`,
        module: `${target.rel}/lib/module/${target.path}.js`,
        types: `${target.rel}/lib/typescript/${target.path}.d.ts`,
        'react-native': `${target.rel}/src/${target.path}.ts`,
        sideEffects: name.endsWith('number'),
      },
      null,
      2,
    ) + '\n'
  );
}

async function main() {
  const files = new Map();
  const seen = new Map();
  for (const s of STRATEGIES) {
    for (const n of [...kernelSpecs(s).map(k => k.name), ...facilitatorSpecs(s).map(f => f.name)]) {
      if (seen.has(n)) throw new Error(`Name collision: ${n} (${seen.get(n)} / ${s.dir})`);
      seen.set(n, s.dir);
    }
    const dir = path.join(ROOT, 'src', 'strategies', s.dir);
    files.set(path.join(dir, 'index.ts'), genIndex(s));
    files.set(path.join(dir, 'number.ts'), genNumber(s));
    if (s.dir !== 'scaled') {
      files.set(
        path.join(ROOT, s.dir, 'package.json'),
        proxy(s.dir, {rel: '..', path: `strategies/${s.dir}/index`}),
      );
      files.set(
        path.join(ROOT, s.dir, 'number', 'package.json'),
        proxy(`${s.dir}/number`, {rel: '../..', path: `strategies/${s.dir}/number`}),
      );
    }
  }
  files.set(
    path.join(ROOT, 'number', 'package.json'),
    proxy('number', {rel: '..', path: 'number'}),
  );
  files.set(
    path.join(ROOT, 'resize', 'package.json'),
    proxy('resize', {rel: '..', path: 'resize/index'}),
  );
  files.set(
    path.join(ROOT, 'units', 'package.json'),
    proxy('units', {rel: '..', path: 'units/index'}),
  );
  files.set(
    path.join(ROOT, 'custom', 'package.json'),
    proxy('custom', {rel: '..', path: 'custom/index'}),
  );
  files.set(
    path.join(ROOT, 'custom', 'number', 'package.json'),
    proxy('custom/number', {rel: '../..', path: 'custom/number'}),
  );

  const config = (await prettier.resolveConfig(path.join(ROOT, 'src', 'index.ts'))) || {};
  let stale = 0;
  for (const [file, raw] of files) {
    const content = file.endsWith('.ts')
      ? await prettier.format(raw, {...config, filepath: file})
      : raw;
    const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
    if (current === content) continue;
    if (CHECK) {
      stale++;
      console.error(`stale: ${path.relative(ROOT, file)}`);
      continue;
    }
    fs.mkdirSync(path.dirname(file), {recursive: true});
    fs.writeFileSync(file, content);
    console.log(`wrote ${path.relative(ROOT, file)}`);
  }
  if (CHECK && stale) {
    console.error(`\n${stale} generated file(s) are stale — run \`npm run generate\`.`);
    process.exit(1);
  }
  console.log(`${seen.size} generated names across ${STRATEGIES.length} strategies.`);
}

main().catch(e => {
  console.error(e);
  process.exit(1);
});
